const input = $input.first().json;
const BASE = 'https://194.195.92.107:444/rest/default/V1/lauka/products';
const parts = [];

// Paginación
const pagina = parseInt(input.pagina) || 1;
parts.push(`searchCriteria[currentPage]=${pagina}`);
parts.push(`searchCriteria[pageSize]=20`);

// Ordenamiento
const ordenar = (input.ordenar_por || '').trim().toLowerCase();
if (ordenar === 'bestsellers') {
  parts.push('sort=bestsellers');
} else if (ordenar === 'precio_asc') {
  parts.push('searchCriteria[sortOrders][0][field]=sale_price');
  parts.push('searchCriteria[sortOrders][0][direction]=ASC');
} else if (ordenar === 'precio_desc') {
  parts.push('searchCriteria[sortOrders][0][field]=sale_price');
  parts.push('searchCriteria[sortOrders][0][direction]=DESC');
} else if (ordenar === 'nombre') {
  parts.push('searchCriteria[sortOrders][0][field]=short_description');
  parts.push('searchCriteria[sortOrders][0][direction]=ASC');
}

let groupIdx = 0;

// Búsqueda por término: solo en campos confiables (SIN sku ni skux)
// Usamos filterGroups con OR dentro del mismo grupo
const q = (input.termino_busqueda || '').trim();
if (q) {
  const val = encodeURIComponent('%' + q + '%');
  const camposBusqueda = [
    'short_description',
    'description',
    'tags',
    'grupo',
    'subcategoria',
    'categories',
    'material',
    'tipo_capacidad',
    'caracteristica_1',
    'caracteristica_2'
  ];
  camposBusqueda.forEach((campo, i) => {
    parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][${i}][field]=${campo}`);
    parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][${i}][value]=${val}`);
    parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][${i}][condition_type]=like`);
  });
  groupIdx++;
}

// Marca (AND con la búsqueda, grupo separado)
const marca = (input.marca || '').trim();
if (marca) {
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][field]=brand`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][value]=${encodeURIComponent(marca)}`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][condition_type]=eq`);
  groupIdx++;
}

// Categoría / subcategoría
const categoria = (input.categoria || '').trim();
if (categoria) {
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][field]=subcategoria`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][value]=${encodeURIComponent('%' + categoria + '%')}`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][condition_type]=like`);
  groupIdx++;
}

// Material
const material = (input.material || '').trim();
if (material) {
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][field]=material`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][value]=${encodeURIComponent('%' + material + '%')}`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][condition_type]=like`);
  groupIdx++;
}

// Precio mínimo
const precioMin = (input.precio_minimo || '').trim();
if (precioMin) {
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][field]=sale_price`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][value]=${encodeURIComponent(precioMin)}`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][condition_type]=gteq`);
  groupIdx++;
}

// Precio máximo
const precioMax = (input.precio_maximo || '').trim();
if (precioMax) {
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][field]=sale_price`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][value]=${encodeURIComponent(precioMax)}`);
  parts.push(`searchCriteria[filterGroups][${groupIdx}][filters][0][condition_type]=lteq`);
  groupIdx++;
}

const url = `${BASE}?${parts.join('&')}`;
return [{ json: { url, termino_busqueda: q } }];

const data = $input.first().json;
const items = data.items || [];
const totalCount = data.total_count || 0;
const sc = data.search_criteria || {};

// Obtener el término de búsqueda del nodo anterior para filtrar client-side
const terminoBusqueda = ($('Construir URL').first().json.termino_busqueda || '').toLowerCase().trim();

if (items.length === 0) {
  return [{ json: { resultado: 'No se encontraron productos.', total: 0, productos: [] } }];
}

// Función: normaliza texto para comparación (quita acentos, minúsculas)
function normalizar(texto) {
  return (texto || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

// Filtro client-side: descarta productos cuyo short_description Y description
// no contienen el término buscado (segunda línea de defensa contra falsos positivos del sku)
const terminoNorm = normalizar(terminoBusqueda);

const productosFiltrados = items.filter(p => {
  if (!terminoNorm) return true; // sin término = sin filtro
  const descCorta = normalizar(p.short_description);
  const desc = normalizar(p.description);
  const grupo = normalizar(p.grupo);
  const subcat = normalizar(p.subcategoria);
  const tags = normalizar((p.tags || ''));
  const tipoCapacidad = normalizar(p.tipo_capacidad);
  return descCorta.includes(terminoNorm)
    || desc.includes(terminoNorm)
    || grupo.includes(terminoNorm)
    || subcat.includes(terminoNorm)
    || tags.includes(terminoNorm)
    || tipoCapacidad.includes(terminoNorm);
});

if (productosFiltrados.length === 0) {
  return [{ json: {
    resultado: `No se encontraron productos relevantes para "${terminoBusqueda}". Intenta con términos relacionados o contacta a Lauka directamente.`,
    total: 0,
    productos: []
  } }];
}

const productos = productosFiltrados.map(p => ({
  product_id: p.product_id,
  skux: p.skux || '',
  nombre: p.short_description || '',
  descripcion: p.description || '',
  marca: p.brand || '',
  precio_regular: p.regular_price || '0.00',
  precio_venta: p.sale_price || '0.00',
  stock: p.stock ?? 0,
  subcategoria: p.subcategoria || '',
  grupo: p.grupo || '',
  tipo_capacidad: p.tipo_capacidad || '',
  material: p.material || '',
  url_producto: `https://194.195.92.107:444/productos/product/view/id/${p.product_id}`
}));

return [{ json: {
  total: productosFiltrados.length,
  total_en_catalogo: totalCount,
  pagina_actual: sc.current_page || 1,
  resultados_en_pagina: productosFiltrados.length,
  productos
} }];

